# Build the 22x25 test grid and fill the interiors of the four outlined rectangles with 7.
g=[[0]*25 for _ in range(22)]
# Rectangle outlines: (top, left, bottom, right, border color)
rects=[(3,2,10,9,4),(2,12,9,19,8),(11,17,16,22,3),(16,4,20,8,9)]
for top,left,bottom,right,color in rects:
    for c in range(left,right+1):
        g[top][c]=color; g[bottom][c]=color
    for r in range(top,bottom+1):
        g[r][left]=color; g[r][right]=color
for top,left,bottom,right,color in rects:
    for r in range(top+1,bottom):
        for c in range(left+1,right):
            g[r][c]=7
print('dimensions',len(g),len(g[0]),'values',sorted(set(x for row in g for x in row)))
print('grid =',repr(g))
